import {deposit} from './society.js';
import {VEHICLES} from './equipment.js';
export const TILE_SIZE=200;
export const NODE_NAMES={food:'Pangan liar',wood:'Hutan',stone:'Batu',ore:'Bijih logam'};
const civ=s=>s._context?.civ||s.world?.settlements[0],root=s=>s._context?.root||s,st=(r,c)=>c.id===1?r:c.state,dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),alive=s=>s.agents.filter(a=>a.alive),has=(s,id)=>civ(s)?.discoveries.includes(id);
const hash=(seed,n)=>(Math.imul((seed^Math.imul(n,2654435761))>>>0,2246822507)>>>0);
export function initFrontier(rootState){const w=rootState.world;if(!w)return;if(!w.nodes){w.nodes=[];for(let planet=0;planet<3;planet++){
 const villages=w.settlements.filter(c=>c.planet===planet),base=villages[0]||{x:1500,y:1000};let positions;
 if(villages.length===4){positions= villages.flatMap(c=>[['food',c.x-150,c.y-120],['wood',c.x+180,c.y+180]]);positions.push(['stone',1050,750],['stone',1950,1150],['ore',350,1600],['ore',2900,400]);}
 else {positions=[['food',base.x-150,base.y-120],['wood',base.x+180,base.y+180],['stone',base.x+150,base.y-150],['ore',550,350],['food',1100,350],['wood',2600,350],['stone',450,1100],['ore',2750,1100],['food',450,1750],['wood',1150,1750],['stone',2050,1750],['ore',2800,1750]];}
 for(const [kind,x,y]of positions){const id=w.nodes.length+1,capacity=100+hash(rootState.seed,id)%201;w.nodes.push({id,planet,kind,x,y,stock:capacity,capacity,renewal:kind==='food'?.4:kind==='wood'?.08:0,owner:null,seenBy:[]});}
 }}
 w.claims??=Array.from({length:480},(_,i)=>({planet:Math.floor(i/160),col:i%16,row:Math.floor(i%160/16),owner:null}));for(const c of w.settlements){c.explored??=[];claimHome(rootState,c);reveal(rootState,c,c,260,()=>{});}}
export function tileKey(planet,x,y){return planet+':'+Math.floor(x/TILE_SIZE)+':'+Math.floor(y/TILE_SIZE);}
function claimHome(r,c){const size=320+Math.min(280,Math.sqrt(Object.values(st(r,c).buildings).reduce((n,x)=>n+x,0))*20);for(const t of r.world.claims)if(t.planet===c.planet&&t.owner===null&&dist(c,{x:(t.col+.5)*TILE_SIZE,y:(t.row+.5)*TILE_SIZE})<size)t.owner=c.id;for(const n of r.world.nodes){const t=r.world.claims[n.planet*160+Math.floor(n.y/TILE_SIZE)*16+Math.floor(n.x/TILE_SIZE)];n.owner=t?.owner??null;}}
function reveal(r,c,pos,radius,log){let found=0;for(const n of r.world.nodes)if(n.planet===c.planet&&dist(n,pos)<=radius){if(!n.seenBy.includes(c.id)){n.seenBy.push(c.id);found++;}if(n.owner&&n.owner!==c.id&&!c.contacts.includes(n.owner)){const other=r.world.settlements.find(x=>x.id===n.owner);c.contacts.push(other.id);other.contacts.push(c.id);c.relations[other.id]=other.relations[c.id]=0;r.world.contacts++;log(st(r,c),'Penjelajah bertemu '+other.name+'.');}}const key=tileKey(c.planet,pos.x,pos.y);if(!c.explored.includes(key))c.explored.push(key);return found;}
export function beginFrontierDay(r,log){for(const n of r.world.nodes)n.stock=Math.min(n.capacity,n.stock+n.renewal*(r.world.settlements.some(c=>c.planet===n.planet&&c.discoveries.includes('forestry'))&&n.kind==='wood'?1.5:1));for(const c of r.world.settlements){claimHome(r,c);const s=st(r,c);for(const a of s.agents){if(!a.alive&&a.journey){const v=s.vehicles.find(v=>v.id===a.journey.vehicle);if(v)v.condition=0;a.journey=null;}if(a.journey?.kind==='campaign'&&a.journey.phase!=='return'&&(!c.war||c.war.against!==a.journey.opponent))returnHome(s,a);}}}
function access(r,c,node){if(!node.owner)return true;const owner=r.world.settlements.find(x=>x.id===node.owner);return owner?.polityId===c.polityId||(c.relations[node.owner]||0)>=60;}
export function gatherTarget(s,kind){const c=civ(s),r=root(s);if(!r.world||!c)return null;return r.world.nodes.filter(n=>n.planet===c.planet&&n.kind===kind&&n.stock>=1&&n.seenBy.includes(c.id)&&access(r,c,n)).sort((a,b)=>dist(a,c)-dist(b,c))[0]||null;}
export function resourceNeed(s){const n=alive(s).length;if(s.food<n*4)return 'food';if(s.wood<100)return 'wood';if(s.stone<70)return 'stone';if(has(s,'metallurgy')&&s.ore<20)return 'ore';return null;}
export function resourcePressure(s){const kind=resourceNeed(s),c=civ(s),r=root(s);if(!kind||!c||!r.world||gatherTarget(s,kind))return null;return r.world.nodes.filter(n=>n.kind===kind&&n.planet===c.planet&&n.stock>=1&&n.seenBy.includes(c.id)&&n.owner&&!access(r,c,n)).sort((a,b)=>dist(a,c)-dist(b,c))[0]||null;}
export function needsExploration(s){const c=civ(s);return !!(c&&resourceNeed(s)&&!gatherTarget(s,resourceNeed(s))&&!resourcePressure(s)&&c.explored.length<160);}
function vehicleFor(s){const leased=new Set(s.agents.filter(a=>a.alive&&a.journey).map(a=>a.journey.vehicle));return s.vehicles.filter(v=>v.condition>0&&!leased.has(v.id)&&(v.type!=='motor'||s.industry.fuel>=5)).sort((a,b)=>b.speed-a.speed)[0]||null;}
function start(s,a,target,kind,amount,log,extra={}){target={...target,x:Math.max(0,Math.min(3199,target.x)),y:Math.max(0,Math.min(1999,target.y))};const c=civ(s);if(a.journey||a.away||!c)return false;const vehicle=vehicleFor(s),speed=vehicle?.speed||100,distance=dist(c,target),days=Math.max(1,Math.ceil(distance/speed)),provisions=Math.max(1,(days*2+2+(kind==='campaign'?30:0))*.35*(kind==='campaign'&&has(s,'militaryLogistics')?.8:1));if(kind==='campaign'&&s.food<provisions)return false;const packed=Math.min(s.food,provisions);s.food-=packed;if(vehicle?.type==='motor')s.industry.fuel-=5;a.journey={kind,source:extra.source||'node',node:target.id??null,customKey:extra.customKey??null,target:{x:target.x,y:target.y},position:{x:c.x,y:c.y},phase:'outbound',remaining:days,total:days,provisions:packed,cargo:{},amount:Math.min(vehicle?.capacity||16,amount),speed,vehicle:vehicle?.id||null,opponent:extra.opponent??null};a.resourceTarget=target.kind||extra.customKey||kind;return true;}
export function startGather(s,a,kind,amount,log){const c=civ(s),r=root(s),node=gatherTarget(s,kind);if(!node)return {reward:-1,energy:1,note:'Tidak ada deposit yang dapat diakses; perlu eksplorasi / perundingan'};const owner=node.owner?r.world.settlements.find(x=>x.id===node.owner):null,payment=owner&&owner.polityId!==c.polityId?Math.min(5,amount*.15):0;if(s.food<payment)return {reward:-1,energy:1};s.food-=payment;if(!start(s,a,node,'gather',amount,log)){s.food+=payment;return {reward:-1,energy:1};}if(payment)st(r,owner).food+=payment;return {reward:2,energy:3,target:NODE_NAMES[kind],note:'Berangkat; hasil masuk persediaan setelah pulang'};}
export function startObjectGather(s,a,object,kind,amount,log){if(!object)return {reward:-1,energy:1};const c=civ(s),d=object.descriptor,target={id:object.id,x:c.x+(d.x-50)*5,y:c.y+(d.y-50)*5};return start(s,a,target,'gather',amount,log,{source:'object'})?{reward:2,energy:3,target:d.name}:{reward:-1,energy:1};}
export function startCustomGather(s,a,resource,amount,log){if(!resource)return {reward:-1,energy:1};const c=civ(s),target={x:c.x+(resource.x-50)*5,y:c.y+(resource.y-50)*5};return start(s,a,target,'gather',amount,log,{source:'custom',customKey:resource.key})?{reward:2,energy:3,target:resource.name}:{reward:-1,energy:1};}
export function startExplore(s,a,log){const c=civ(s),r=root(s);const reserved=new Set(s.agents.filter(a=>a.alive&&a.journey?.kind==='explore'&&a.journey.phase==='outbound').map(a=>tileKey(c.planet,a.journey.target.x,a.journey.target.y)));const choices=r.world.claims.filter(t=>!reserved.has(tileKey(c.planet,(t.col+.5)*200,(t.row+.5)*200))&&t.planet===c.planet&&!c.explored.includes(tileKey(c.planet,(t.col+.5)*200,(t.row+.5)*200))).map(t=>({x:(t.col+.5)*200,y:(t.row+.5)*200})).sort((x,y)=>dist(x,c)-dist(y,c));return choices.length&&start(s,a,choices[0],'explore',0,log)?{reward:3,energy:3,note:'Menjelajah wilayah yang belum dikenal'}:{reward:-1,energy:1};}
export function startCampaign(s,a,log){const c=civ(s),node=root(s).world.nodes.find(n=>n.id===c.war?.claim);if(!node)return {reward:-1,energy:1};return start(s,a,node,'campaign',0,log,{opponent:c.war.against})?{reward:3,energy:3,target:NODE_NAMES[node.kind],note:'Berangkat ke deposit yang diperebutkan'}:{reward:-1,energy:1};}
function returnHome(s,a){const j=a.journey,c=civ(s);j.phase='return';j.remaining=j.total=Math.max(1,Math.ceil(dist(j.position,c)/j.speed));}
export function journeyWork(s,a,log){const j=a.journey,c=civ(s),r=root(s);if(!j)return {reward:-1,energy:1};if(j.phase==='camp'){if(!c.war)returnHome(s,a);else {if(j.provisions>=.25){j.provisions-=.25;a.hunger=Math.max(0,a.hunger-8);a.energy=Math.min(100,a.energy+27);}else a.health=Math.max(0,a.health-1);return {reward:1,energy:0,note:'Istirahat dan menggunakan bekal di front'};}}
 if(j.provisions>=.25){j.provisions-=.25;a.hunger=Math.max(0,a.hunger-8);a.energy=Math.min(100,a.energy+7);}else{a.health=Math.max(0,a.health-1);}
 const target=j.phase==='return'?c:j.target;j.position.x+=(target.x-j.position.x)/Math.max(1,j.remaining);j.position.y+=(target.y-j.position.y)/Math.max(1,j.remaining);j.remaining--;
 if(j.remaining>0)return {reward:1,energy:3,note:j.phase+' · '+j.remaining+' hari'};
 if(j.phase==='outbound'){const found=reveal(r,c,j.position,260,log);if(found&&j.kind==='explore')log(s,'Eksplorasi menemukan '+found+' deposit.');if(j.kind==='campaign'){j.phase='camp';j.remaining=1;return {reward:2,energy:2,note:'Tiba di front sumber daya'};}if(j.kind==='explore'){returnHome(s,a);return {reward:found?5:1,energy:2};}j.phase='harvest';j.remaining=1;return {reward:1,energy:2};}
 if(j.phase==='harvest'){let n=j.source==='node'?r.world.nodes.find(n=>n.id===j.node):j.source==='object'?s.objects.find(o=>o.id===j.node):s.customResources.find(o=>o.key===j.customKey);if(n&&(j.source!=='node'||access(r,c,n))){const amount=Math.min(n.stock,j.amount);n.stock-=amount;if(j.source==='custom'){j.cargo.custom=amount;a.health=Math.max(0,a.health-amount*n.toxicity*.02);}else{const key=j.source==='node'?n.kind:n.kind==='forest'?'wood':n.kind==='quarry'?'stone':'food';j.cargo[key]=amount;if(key==='food'){j.cargo.fiber=amount*.12;j.cargo.bone=amount*.04;}}}returnHome(s,a);return {reward:2,energy:6};}
 if(j.phase==='return'){for(const [k,n]of Object.entries(j.cargo)){if(k==='custom'){const resource=s.customResources.find(x=>x.key===j.customKey);if(resource)resource.amount+=n;}else if(['food','wood','stone'].includes(k))deposit(s,a,k,n);else s[k]+=n;}s.food+=j.provisions;const v=s.vehicles.find(v=>v.id===j.vehicle);if(v){v.uses++;v.condition=Math.max(0,v.condition-(j.total*2+1)*100/VEHICLES[v.type].durability);}a.journey=null;return {reward:4,energy:2,note:'Muatan tiba di permukiman'};}return {reward:0,energy:1};}
export function restoreNature(s,a,scale){const c=civ(s),node=root(s).world.nodes.filter(n=>n.planet===c.planet&&n.renewal>0&&n.stock<n.capacity&&n.seenBy.includes(c.id)&&dist(n,c)<320&&access(root(s),c,n)).sort((a,b)=>a.stock/a.capacity-b.stock/b.capacity)[0];if(!node||s.wood<3)return {reward:-1,energy:1};s.wood-=3;node.stock=Math.min(node.capacity,node.stock+8*scale);return {reward:3,energy:5,target:NODE_NAMES[node.kind]};}
export function captureDeposit(r,node,c,log){const old=node.owner,t=r.world.claims.find(t=>t.planet===node.planet&&t.col===Math.floor(node.x/200)&&t.row===Math.floor(node.y/200));if(t)t.owner=c.id;for(const n of r.world.nodes)if(n.planet===node.planet&&Math.floor(n.x/200)===Math.floor(node.x/200)&&Math.floor(n.y/200)===Math.floor(node.y/200))n.owner=c.id;log(st(r,c),'Wilayah deposit '+NODE_NAMES[node.kind]+' direbut dari '+(r.world.settlements.find(x=>x.id===old)?.name||'wilayah bebas')+'.');}
export function validateFrontierState(s,finite){if(!finite(s.ore,0,1e12)||!Array.isArray(s.weapons)||s.weapons.length>512||!Array.isArray(s.vehicles)||s.vehicles.length>256||!Number.isInteger(s.nextWeaponId)||!Number.isInteger(s.nextVehicleId)||s.nextWeaponId<1||s.nextVehicleId<1||s.nextWeaponId>1e9||s.nextVehicleId>1e9)throw Error('Peralatan / bijih tidak valid.');for(const [list,next]of [[s.weapons,s.nextWeaponId],[s.vehicles,s.nextVehicleId]]){const ids=new Set();for(const v of list){if(!Number.isInteger(v.id)||v.id<1||v.id>=next||ids.has(v.id)||!finite(v.condition,0,100)||!finite(v.uses,0,1e12))throw Error('Peralatan tidak valid.');ids.add(v.id);if(list===s.weapons&&(!(v.owner===null||v.owner===undefined||Number.isInteger(v.owner)&&s.agents.some(a=>a.alive&&a.id===v.owner&&a.equipment.weapon===v.id))))throw Error('Pemilik senjata tidak valid.');if(list===s.weapons&&!['stone','metal','ballistic'].includes(v.type)||list===s.vehicles&&!['cart','motor','biotic'].includes(v.type))throw Error('Jenis peralatan tidak valid.');if(list===s.vehicles&&(v.speed!==VEHICLES[v.type].speed||v.capacity!==VEHICLES[v.type].capacity))throw Error('Kendaraan tidak valid.');}}
 if(s.vehicleProject&&(!['cart','motor','biotic'].includes(s.vehicleProject.type)||!finite(s.vehicleProject.progress,0,40)||s.vehicleProject.required!==40))throw Error('Proyek kendaraan tidak valid.');const leased=new Set();for(const a of s.agents){const j=a.journey;if(j===null)continue;if(!j||a.away||!['gather','explore','campaign'].includes(j.kind)||!['node','object','custom'].includes(j.source)||!['outbound','harvest','return','camp'].includes(j.phase)||(j.phase==='camp'&&j.kind!=='campaign')||!Number.isInteger(j.remaining)||!Number.isInteger(j.total)||!finite(j.remaining,1,j.total)||!finite(j.total,1,100)||!finite(j.speed,100,400)||!finite(j.provisions,0,100)||!finite(j.amount,0,80)||!j.cargo||Object.entries(j.cargo).some(([k,n])=>!['food','wood','stone','ore','fiber','bone','custom'].includes(k)||!finite(n,0,100))||j.vehicle!==null&&!s.vehicles.some(v=>v.id===j.vehicle))throw Error('Perjalanan warga tidak valid.');const vehicle=s.vehicles.find(v=>v.id===j.vehicle);if(j.speed!==(vehicle?.speed||100)||j.amount>(vehicle?.capacity||16)||vehicle&&a.alive&&leased.has(vehicle.id))throw Error('Penyewaan kendaraan tidak valid.');if(vehicle&&a.alive)leased.add(vehicle.id);for(const p of [j.target,j.position])if(!p||!finite(p.x,0,3200)||!finite(p.y,0,2000))throw Error('Posisi perjalanan tidak valid.');}}
export function validateFrontier(r,finite){const w=r.world,ids=new Set(w.settlements.map(c=>c.id));if(!Array.isArray(w.nodes)||![36,108].includes(w.nodes.length)||!Array.isArray(w.claims)||w.claims.length!==480)throw Error('Geografi resource tidak valid.');const nodeIds=new Set();for(const n of w.nodes){if(!Number.isInteger(n.id)||n.id<1||!Number.isInteger(n.planet)||nodeIds.has(n.id)||!w.planets[n.planet]||!Object.hasOwn(NODE_NAMES,n.kind)||!finite(n.x,0,3200)||!finite(n.y,0,2000)||!finite(n.capacity,1,1e6)||!finite(n.stock,0,n.capacity)||!finite(n.renewal,0,1)||(['stone','ore'].includes(n.kind)&&n.renewal!==0)||n.owner!==null&&!ids.has(n.owner)||!Array.isArray(n.seenBy)||new Set(n.seenBy).size!==n.seenBy.length||n.seenBy.some(id=>!ids.has(id)))throw Error('Deposit tidak valid.');nodeIds.add(n.id);}const tileIds=new Set();for(const [index,t]of w.claims.entries()){if(t.planet!==Math.floor(index/160)||t.row!==Math.floor(index%160/16)||t.col!==index%16)throw Error('Urutan peta wilayah tidak valid.');const key=t.planet+':'+t.col+':'+t.row;if(tileIds.has(key)||!Number.isInteger(t.planet)||!w.planets[t.planet]||!Number.isInteger(t.col)||!finite(t.col,0,15)||!Number.isInteger(t.row)||!finite(t.row,0,9)||t.owner!==null&&!ids.has(t.owner))throw Error('Batas wilayah tidak valid.');tileIds.add(key);}for(const c of w.settlements){if(!Array.isArray(c.explored)||c.explored.length>160||new Set(c.explored).size!==c.explored.length||c.explored.some(k=>!tileIds.has(k)||!k.startsWith(c.planet+':')))throw Error('Wilayah eksplorasi tidak valid.');for(const a of st(r,c).agents){const j=a.journey;if(j?.source==='node'&&j.kind!=='explore'&&!w.nodes.some(n=>n.id===j.node&&n.planet===c.planet)||j?.source==='object'&&!st(r,c).objects.some(o=>o.id===j.node)||j?.source==='custom'&&!st(r,c).customResources.some(o=>o.key===j.customKey))throw Error('Tujuan perjalanan tidak valid.');}}}
